/* Deepotsav service worker.
 * - Precaches the whole app shell (it is small and fully procedural) so the
 *   experience works offline after the first visit.
 * - Navigations: network first, falling back to the cached app, then to
 *   offline.html.
 * - Everything else (same origin): cache first with background refresh.
 * - A new version waits until the page asks it to take over ("Refresh" toast).
 * The VERSION and PRECACHE list are regenerated by `npm run release`.
 */

/* RELEASE:START */
const VERSION = 'deepotsav-1.0.0-ceb78b084e';
const PRECACHE = [
  './',
  './assets/fonts/cormorant-500-italic.woff2',
  './assets/fonts/cormorant-500.woff2',
  './assets/fonts/cormorant-600.woff2',
  './assets/fonts/mukta-400.woff2',
  './assets/fonts/mukta-600.woff2',
  './assets/fonts/mukta-deva-400.woff2',
  './assets/fonts/mukta-deva-600.woff2',
  './assets/fonts/mukta-ext-400.woff2',
  './assets/icons/apple-touch-icon.png',
  './assets/icons/favicon-32.png',
  './assets/icons/icon-192.png',
  './assets/icons/icon-512.png',
  './assets/icons/icon-maskable-512.png',
  './assets/icons/icon.svg',
  './assets/og-image.png',
  './css/styles.css',
  './index.html',
  './js/boot.js',
  './js/config.js',
  './js/core/a11y.js',
  './js/core/audio.js',
  './js/core/cameraRig.js',
  './js/core/engine.js',
  './js/core/pwa.js',
  './js/core/quality.js',
  './js/core/router.js',
  './js/core/storage.js',
  './js/core/store.js',
  './js/core/ui.js',
  './js/fallback/fallback2d.js',
  './js/gfx/chunks.js',
  './js/gfx/fireworks.js',
  './js/gfx/heroDiya.js',
  './js/gfx/lampField.js',
  './js/gfx/lighting.js',
  './js/gfx/palace.js',
  './js/gfx/sky.js',
  './js/gfx/textures.js',
  './js/gfx/volumetrics.js',
  './js/gfx/water.js',
  './js/greetings/card.js',
  './js/greetings/link.js',
  './js/greetings/presets.js',
  './js/lib/gsap.js',
  './js/lib/three.js',
  './js/main.js',
  './js/rangoli/generator.js',
  './js/rangoli/studio.js',
  './js/scenes/palaceScene.js',
  './js/scenes/riverScene.js',
  './js/worlds/fireworks.js',
  './js/worlds/greetings.js',
  './js/worlds/ignite.js',
  './js/worlds/meaning.js',
  './js/worlds/rangoli.js',
  './js/worlds/story.js',
  './js/worlds/wishes.js',
  './manifest.webmanifest',
  './offline.html',
  './vendor/gsap/gsap-core.js',
  './vendor/three/addons/objects/Reflector.js',
  './vendor/three/addons/postprocessing/EffectComposer.js',
  './vendor/three/addons/postprocessing/MaskPass.js',
  './vendor/three/addons/postprocessing/OutputPass.js',
  './vendor/three/addons/postprocessing/Pass.js',
  './vendor/three/addons/postprocessing/RenderPass.js',
  './vendor/three/addons/postprocessing/ShaderPass.js',
  './vendor/three/addons/postprocessing/UnrealBloomPass.js',
  './vendor/three/addons/shaders/CopyShader.js',
  './vendor/three/addons/shaders/LuminosityHighPassShader.js',
  './vendor/three/addons/shaders/OutputShader.js',
  './vendor/three/addons/utils/BufferGeometryUtils.js',
  './vendor/three/three.module.min.js',
];
/* RELEASE:END */

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(VERSION).then((cache) => cache.addAll(PRECACHE)).catch((err) => console.warn('[sw] precache failed', err)),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('deepotsav-') && k !== VERSION).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(req);
        const cache = await caches.open(VERSION);
        cache.put('./index.html', fresh.clone()).catch(() => {});
        return fresh;
      } catch {
        const cache = await caches.open(VERSION);
        return (await cache.match('./index.html')) || (await cache.match('./offline.html')) || new Response('Offline', { status: 503 });
      }
    })());
    return;
  }

  event.respondWith((async () => {
    const cache = await caches.open(VERSION);
    const cached = await cache.match(req, { ignoreSearch: true });
    const network = fetch(req).then((res) => {
      if (res && res.ok && res.type === 'basic') cache.put(req, res.clone()).catch(() => {});
      return res;
    }).catch(() => null);
    if (cached) {
      event.waitUntil(network);
      return cached;
    }
    const res = await network;
    return res || new Response('', { status: 504, statusText: 'Offline' });
  })());
});
